class AccessRequest(_rt.ContractModel):
    """A device outside its access hours asks for access now. One open request per device. answer is
    set exactly for approved/declined. The requesting device sees status, answer (answer, duration,
    until, message, by.name) and recipients; recipients and the admin also see the device and its
    note. Times in UTC. tools/validate.py checks that answer is an object exactly for approved and
    declined.
    Schema: schemas/common/access-request.json
    """

    request_id: StrictStr
    client_id: StrictStr
    device_name: StrictStr
    owner_label: StrictStr | None = None
    profile_kind: ProfileKindValue | None = None
    note: StrictStr | None = None
    status: AccessRequestStatusValue
    created_at: StrictStr
    expires_at: StrictStr
    opens_at: StrictStr | None
    durations: list[AccessRequestDurationValue] = Field(description='Durations a Yes may give for this request (until_window_start only with a known opens_at at most until_window_start_max_hours ahead).')
    recipients: list[AccessRequestRecipientsItem]
    can_answer: StrictBool | None = Field(None, description='Only in the copy for a recipient device: it may answer now.')
    answer: AccessRequestAnswer | None

    def _check(self, p: str, e: list[str]) -> None:
        _rt.check_str(e, p + "/request_id", self.request_id, pattern=_RE_1)
        _rt.check_str(e, p + "/client_id", self.client_id, pattern=_RE_1)
        _rt.check_str(e, p + "/device_name", self.device_name, max_length=100)
        _rt.check_str(e, p + "/owner_label", self.owner_label, max_length=50)
        _rt.check_enum(e, p + "/profile_kind", self.profile_kind, ProfileKind)
        _rt.check_str(e, p + "/note", self.note, max_length=80)
        _rt.check_enum(e, p + "/status", self.status, AccessRequestStatus)
        _rt.check_items(e, p + "/durations", self.durations, unique=True)
        for i0, x0 in enumerate(self.durations or ()):
            _rt.check_enum(e, f"{p + "/durations"}/{i0}", x0, AccessRequestDuration)
        _rt.check_items(e, p + "/recipients", self.recipients, max_items=10)
        for i0, x0 in enumerate(self.recipients or ()):
            _rt.check_model(e, f"{p + "/recipients"}/{i0}", x0)
        _rt.check_model(e, p + "/answer", self.answer)


