class TileSettings(_rt.ContractModel):
    """Per-placement presentation and behavior of an entity card as delivered by the hub (WS get_area,
    Admin REST). The writable fields are defs.json#/$defs/tile_settings_base; icon_svg and
    secondary_state are hub output and never accepted on write. {} = everything default. An app may
    ignore the settings and show the standard card (guests always do); apps that do not know the
    field ignore it (tolerant decoding). Fallback rules: docs/protocol.md, Tile settings.
    Schema: schemas/common/tile-settings.json
    """

    icon: StrictStr | None = Field(None, description="null = Home Assistant icon (attributes.icon), else the app's domain/state symbol. A custom icon is static (replaces the state-dependent symbol).")
    variant: TileVariantValue | None = None
    secondary: TileSecondary | None = None
    tap_action: TileTapAction | None = None
    hold_action: TileHoldAction | None = None
    confirm: StrictBool | None = Field(None, description='Ask before toggle/run. Locks and alarm panels always confirm (field not allowed there).')
    accent: TileAccentValue | None = Field(None, description='Palette color family, applied only while the entity is active. null = domain tint.')
    hidden_on: list[TileFormFactorValue] | None = Field(None, description='Form factors that do not show this card (1-2 entries; all three = use is_visible). Filtered by the app, not a security boundary.')
    icon_svg: StrictStr | None = Field(None, description='Hub output: SVG path of the effective MDI icon (tile.icon when mdi:, else an mdi: icon set in Home Assistant, attributes.icon). null or absent for sf: icons and when no MDI icon applies.')
    secondary_state: TileSettingsSecondaryState | None = Field(None, description='Hub output for secondary.source=entity: state of secondary.entity_id at request time (sanitized like area-entity.state); null when unavailable.')

    def _check(self, p: str, e: list[str]) -> None:
        _rt.check_str(e, p + "/icon", self.icon, pattern=_RE_10, max_length=100)
        _rt.check_enum(e, p + "/variant", self.variant, TileVariant)
        _rt.check_model(e, p + "/secondary", self.secondary)
        _rt.check_model(e, p + "/tap_action", self.tap_action)
        _rt.check_model(e, p + "/hold_action", self.hold_action)
        _rt.check_enum(e, p + "/accent", self.accent, TileAccent)
        _rt.check_items(e, p + "/hidden_on", self.hidden_on, min_items=1, max_items=2, unique=True)
        for i0, x0 in enumerate(self.hidden_on or ()):
            _rt.check_enum(e, f"{p + "/hidden_on"}/{i0}", x0, TileFormFactor)
        _rt.check_str(e, p + "/icon_svg", self.icon_svg, max_length=10000)
        _rt.check_model(e, p + "/secondary_state", self.secondary_state)


