class PanelStatus(_rt.ContractModel):
    """Live status of a device for Home Assistant, reported by the app in client_status.panel and
    echoed in panel_command_ok. Every app with a hub connection sends it, not only wall panels: on a
    wall panel (iPad or Android tablet in wall panel mode) and on a TV the screen state, on every
    other device (phone, tablet without wall panel) whether the app is in front (screen active) or
    not (off). The hub keeps only the last value (no history), checks enums and ranges and drops
    invalid fields silently. No touch timestamp: the coarse screen state is enough for automations
    and is not a presence log. Reserved for later app versions: the capabilities pip,
    proximity_sensor, device_admin, device_owner, background_connection, nfc, charge_limit_detected
    and the Android values battery_temperature and battery_health.
    Schema: schemas/common/panel-status.json
    """

    screen: PanelScreenValue | None = None
    panel_mode: StrictBool | None = Field(None, description='True while the wall panel mode (iPad, Android tablet) or the kiosk (Apple TV, Android TV) is shown; false when the app runs normally (phones always false). Outside the panel mode screen is only active (app in front) or off (app in the background, or the device left it), and panel_command is answered with not_in_panel_mode.')
    brightness: _rt.Number | None = Field(None, description='Actual backlight 0–1 (screen brightness of the system on iPhone and iPad, window brightness on Android). Phones and tablets outside the wall panel mode: only while the app is in front, null in the background (iOS lets no app read the brightness there). null on Apple TV.')
    brightness_mode: PanelBrightnessModeValue | None = None
    illuminance: _rt.Number | None = Field(None, description='Android only: light sensor of the device in lx (median over a few seconds; sent on a change of 15 % or 5 lx, at most every 10 s). iPadOS has no light sensor API for apps.')
    actions: list[PanelActionValue] | None = Field(None, description='Capabilities: the panel_command actions this app supports right now (iPad: all except screen_off; Apple TV: wake, screensaver, home, reload; Android: plus screen_off depending on the lock level). The hub rejects other actions with unsupported.')
    light_sensor: StrictBool | None = Field(None, description='Android: the device has a light sensor (illuminance possible).')
    lock: PanelLockValue | None = Field(None, description='Android lock level: none, pinning, lock_task (device owner), device_admin.')
    pip: StrictBool | None = Field(None, description='picture-in-picture is available (Apple TV, Google TV, iPad, Android); show_camera can continue in picture-in-picture when the user starts it.')
    proximity_sensor: StrictBool | None = Field(None, description='Android: the device has a proximity sensor (panel_wake proximity possible). The proximity value itself never leaves the device.')
    device_admin: StrictBool | None = Field(None, description='Android: the app is device administrator (panel_off_mode off possible).')
    device_owner: StrictBool | None = Field(None, description='Android: the app is device owner (lock task without confirmation).')
    background_connection: StrictBool | None = Field(None, description='Android: a foreground service keeps the hub connection while the app is not in front.')
    nfc: StrictBool | None = Field(None, description='The device can read NFC tags right now (reader present and switched on).')
    charge_limit_detected: StrictBool | None = Field(None, description='Android: the device limits charging itself (e.g. 80/85 % battery protection); the battery protection blueprint is then not needed.')
    battery_temperature: _rt.Number | None = Field(None, description='Android only: battery temperature in °C (one decimal; sent on a change of 1 °C, at most every 60 s). Sensor battery_temperature of panel_sensors.')
    battery_health: BatteryHealthValue | None = Field(None, description='Android only: battery health (attribute of the sensor battery_temperature).')

    def _check(self, p: str, e: list[str]) -> None:
        _rt.check_enum(e, p + "/screen", self.screen, PanelScreen)
        _rt.check_num(e, p + "/brightness", self.brightness, minimum=0, maximum=1, finite=True)
        _rt.check_enum(e, p + "/brightness_mode", self.brightness_mode, PanelBrightnessMode)
        _rt.check_num(e, p + "/illuminance", self.illuminance, minimum=0, maximum=200000, finite=True)
        _rt.check_items(e, p + "/actions", self.actions, max_items=16, unique=True)
        for i0, x0 in enumerate(self.actions or ()):
            _rt.check_enum(e, f"{p + "/actions"}/{i0}", x0, PanelAction)
        _rt.check_enum(e, p + "/lock", self.lock, PanelLock)
        _rt.check_num(e, p + "/battery_temperature", self.battery_temperature, minimum=-40, maximum=100, finite=True)
        _rt.check_enum(e, p + "/battery_health", self.battery_health, BatteryHealth)


