class LogEntry(_rt.ContractModel):
    """One entry of the log tab of the hub (GET /api/log): activity (who switched what), change
    (profile audit, pairing, guests, parent releases, integration starts) or alarm (rejections from
    a threshold, direct access attempts, integration outages). Names (device, owner, profile) are
    stored with the entry and replaced by the current name while the device/profile exists. No
    action data, codes, IP addresses, PINs or tokens.
    Schema: schemas/common/log-entry.json
    """

    __closed__: ClassVar[bool] = True
    id: StrictInt = Field(description='Ascending; paging with before_id.')
    ts: StrictStr
    category: LogEntryCategoryValue
    kind: StrictStr = Field(description="Fine-grained kind: an event kind of data/events.json, a profile audit action ($defs/profile_audit_action) or a hub kind (device_revoked, kids_release, kids_pause_lifted, integration_dropped, ha_key_withdrawn = the device stopped holding a Home Assistant key (control_path hub without remote access) and the integration has accepted the replacement, so the key the app held no longer works (the hub keeps the device user's new token for the hub path)). device_set_up: detail kind, method (onboard|invite), set_up_by {client_id, name}; actor = name of the setting-up device; texts “Child's iPhone set up by Dad as Child 6–9”. home_networks_set (category change): detail before/after = lists of CIDR. Clients show an unknown kind generically.")
    event_kind: StrictStr | None
    source: LogEntrySourceValue = Field(description='ha = HA call_service event of a device user that switches directly (control path direct).')
    client_id: StrictStr | None
    device_name: StrictStr | None
    owner_label: StrictStr | None
    profile_id: StrictStr | None
    profile_name: StrictStr | None
    area_id: StrictStr | None
    area_name: StrictStr | None
    entity_id: StrictStr | None
    entity_name: StrictStr | None
    action: StrictStr | None
    route: LogEntryRouteValue | None
    origin: LogEntryOriginValue | None
    control_path: LogEntryControlPathValue | None
    result: LogEntryResultValue | None
    reason: StrictStr | None
    count: StrictInt | None
    since: StrictStr | None
    until: StrictStr | None
    actor: StrictStr | None
    detail: dict[str, Any] | None
    device_exists: StrictBool
    profile_exists: StrictBool
    unread: StrictBool = Field(description='Alarm not marked as read.')
    important: StrictBool = Field(description='Entry counts as important: log category alarm, or event_kind/kind marked important in data/events.json. Same rule as the filter important=true of GET /api/log.')

    def _check(self, p: str, e: list[str]) -> None:
        _rt.check_num(e, p + "/id", self.id, minimum=1)
        _rt.check_enum(e, p + "/category", self.category, LogEntryCategory)
        _rt.check_str(e, p + "/kind", self.kind, pattern=_RE_7)
        _rt.check_str(e, p + "/event_kind", self.event_kind, pattern=_RE_19)
        _rt.check_enum(e, p + "/source", self.source, LogEntrySource)
        _rt.check_str(e, p + "/client_id", self.client_id, max_length=64)
        _rt.check_str(e, p + "/device_name", self.device_name, max_length=100)
        _rt.check_str(e, p + "/owner_label", self.owner_label, max_length=50)
        _rt.check_str(e, p + "/profile_id", self.profile_id, max_length=64)
        _rt.check_str(e, p + "/profile_name", self.profile_name, max_length=60)
        _rt.check_str(e, p + "/area_id", self.area_id, max_length=64)
        _rt.check_str(e, p + "/area_name", self.area_name, max_length=100)
        _rt.check_str(e, p + "/entity_id", self.entity_id, pattern=_RE_3, max_length=255)
        _rt.check_str(e, p + "/entity_name", self.entity_name, max_length=255)
        _rt.check_str(e, p + "/action", self.action, pattern=_RE_19)
        _rt.check_enum(e, p + "/route", self.route, LogEntryRoute)
        _rt.check_enum(e, p + "/origin", self.origin, LogEntryOrigin)
        _rt.check_enum(e, p + "/control_path", self.control_path, LogEntryControlPath)
        _rt.check_enum(e, p + "/result", self.result, LogEntryResult)
        _rt.check_str(e, p + "/reason", self.reason, pattern=_RE_19)
        _rt.check_num(e, p + "/count", self.count, minimum=1)
        _rt.check_str(e, p + "/actor", self.actor, max_length=100)
        self._check_object(p, e)


