class ClientAccess(_rt.ContractModel):
    """Access of the device: member or guest, set when pairing and never changed. Guests: expires_at is
    the hub's authoritative end (no own cap in the apps; the hub limits a grant to
    guest_access.max_hours of data/profile-rules.json and announces an extension with guest_extended
    / client_config_updated). After expires_at the hub rejects the device (auth_error guest_expired)
    and the app locks everything (fail closed). hours = access right now (access hours, access
    switch). request = “Ask for early access”.
    Schema: schemas/common/client-access.json
    """

    kind: DeviceAccessValue
    expires_at: StrictStr | None = Field(description='Guests: end of the access (always set). Members: null.')
    set_up_by: SetUpByShown | None = Field(None, description='Member device that set up this device (confirmed its onboarding or invited it as a guest), only as the device may show it: name and method, never the client_id of that device. null or missing after the admin PIN.')
    time_zone: StrictStr = Field(description="IANA time zone of the hub (Home Assistant's time_zone; UTC when Home Assistant names none or an unknown one). The windows of the rule access_hours are in this zone: the app computes every window edge (the next window start after until, the end of a window it opens by itself) in it, never in the device's own zone. Sent to every device, also without access hours.")
    hours: AccessNow = Field(description='Access right now (access hours and access switch). open false: the device stays paired, the hub sends no areas, states or quick access entries and refuses control (rule_blocked access_closed), ha_token and ha_url are null; the app shows only “Access again from {opens_at}” (or “No access right now” without opens_at). The hub sends client_config_updated at every change (window start/end, switch). The app also switches on its own at until/opens_at.')
    request: AccessRequestConfig | None = Field(None, description='Present while the effective rule access_requests is on.')

    def _check(self, p: str, e: list[str]) -> None:
        _rt.check_enum(e, p + "/kind", self.kind, DeviceAccess)
        _rt.check_model(e, p + "/set_up_by", self.set_up_by)
        _rt.check_str(e, p + "/time_zone", self.time_zone, min_length=1, max_length=64)
        _rt.check_model(e, p + "/hours", self.hours)
        _rt.check_model(e, p + "/request", self.request)
        self._check_object(p, e, conditionals=[{'prop': 'kind', 'values': ['guest'], 'presence': True, 'then': {'non_null': ['expires_at']}, 'else': None}])


