class ClientAuth(_rt.ContractModel):
    """Authenticate with the client secret (5 attempts per connection). Query-string tokens are not
    supported. Carries the client info: protocol_version, platform, app_version required, app_build
    and device_model optional. The hub stores them per device (Admin API) and checks them after the
    secret: a valid secret with a too old app yields upgrade_required + close 4426; a tombstoned
    secret still yields client_removed first. Invalid client info (unknown platform, malformed
    version) yields auth_error.
    Schema: schemas/ws/client/auth.json
    """

    __fixed__: ClassVar[dict[str, str]] = {'type': 'auth'}
    type: Literal['auth'] = 'auth'
    secret: StrictStr
    protocol_version: StrictInt = Field(description="Protocol version the app speaks. Missing or below the hub's min_protocol_version: the hub answers upgrade_required and closes 4426.")
    platform: PlatformValue
    app_version: StrictStr = Field(description='Below min_app_version[platform] of the hub: upgrade_required, close 4426.')
    app_build: StrictStr | None = None
    device_model: StrictStr | None = None

    def _check(self, p: str, e: list[str]) -> None:
        _rt.check_str(e, p + "/secret", self.secret, pattern=_RE_15)
        _rt.check_num(e, p + "/protocol_version", self.protocol_version, minimum=1)
        _rt.check_enum(e, p + "/platform", self.platform, Platform)
        _rt.check_str(e, p + "/app_version", self.app_version, pattern=_RE_21, max_length=32)
        _rt.check_str(e, p + "/app_build", self.app_build, pattern=_RE_22)
        _rt.check_str(e, p + "/device_model", self.device_model, pattern=_RE_20)


