    child_protection: StrictBool = Field(description='Parental controls.')
    managed_by: StrictStr | None = Field(None, description='Display name of the hub admin (Home Assistant owner) for texts on the device; null = unknown.')

    def _check(self, p: str, e: list[str]) -> None:
        _rt.check_str(e, p + "/id", self.id, pattern=_RE_1)
        _rt.check_str(e, p + "/name", self.name, pattern=_RE_26, min_length=1, max_length=40)
