class KidsRateLimitAll(_rt.ContractModel):
    """Overall rate limit of a child device (failsafe next to the rate limit per entity): when the
    child switches more than max_entities different entities or more than max_actions actions in
    total within window_seconds, everything pauses for cooldown_seconds (every entity of the device,
    hub path and <ns>.control alike). The action that would exceed a limit is rejected and starts
    the pause (reason paused_all with until). Successful actions count, rejected attempts do not.
    enabled false = off (the values are kept so switching on restores them). A parental release
    (override_until) and the family release kind pause end a running pause and suspend the limit
    until they end.
    """

    __closed__: ClassVar[bool] = True
    enabled: StrictBool
    max_actions: StrictInt = Field(description='Actions in total within the window; one more starts the pause.')
    max_entities: StrictInt = Field(description='Different entities within the window; one more starts the pause.')
    window_seconds: StrictInt
    cooldown_seconds: StrictInt = Field(description='Length of the pause of everything.')

