class ProfileRuleValuesPanelBrightness(_rt.ContractModel):
    """Backlight of the panel while active. Dimmed lowers the real backlight further (panel_dim),
    panel_night stays the upper limit at night. The app smooths changes (hysteresis ±10 %, at most
    one step per 10 s). A value set from Home Assistant switches to manual until the next phase
    change.
    """

    __closed__: ClassVar[bool] = True
    mode: ProfileRuleValuesPanelBrightnessModeValue = Field(description="system = do not touch the backlight (the device decides); fixed = level; lux = curve from the Home Assistant illuminance entity lux_entity (iPad: the only way, iPadOS has no light sensor API for apps); device_lux = the device's own light sensor (Android; without one like lux); schedule = levels at times of day.")
    level: StrictInt | None = Field(None, description='fixed: backlight in percent.')
    lux_entity: StrictStr | None = Field(None, description='lux/device_lux: sensor entity with device_class illuminance (lx).')
    min: StrictInt | None = Field(None, description='lux: backlight at 0 lx (and darker).')
    max: StrictInt | None = Field(None, description='lux: backlight at lux_max and brighter.')
    lux_max: StrictInt | None = Field(None, description='lux: illuminance at which max is reached (default 500).')
    curve: ProfileRuleValuesPanelBrightnessCurveValue | None = Field(None, description='lux: logarithmic (default) or linear between 1 lx and lux_max.')
    schedule: list[ProfileRuleValuesPanelBrightnessScheduleItem] | None = Field(None, description='schedule: from at (local time of the device) on, level applies until the next entry; the last entry wraps over midnight.')

    def _check(self, p: str, e: list[str]) -> None:
        _rt.check_enum(e, p + "/mode", self.mode, ProfileRuleValuesPanelBrightnessMode)
        _rt.check_num(e, p + "/level", self.level, minimum=5, maximum=100)
        _rt.check_str(e, p + "/lux_entity", self.lux_entity, pattern=_RE_27, max_length=255)
        _rt.check_num(e, p + "/min", self.min, minimum=5, maximum=100)
        _rt.check_num(e, p + "/max", self.max, minimum=5, maximum=100)
        _rt.check_num(e, p + "/lux_max", self.lux_max, minimum=10, maximum=100000)
        _rt.check_enum(e, p + "/curve", self.curve, ProfileRuleValuesPanelBrightnessCurve)
        _rt.check_items(e, p + "/schedule", self.schedule, min_items=1, max_items=8)
        for i0, x0 in enumerate(self.schedule or ()):
            _rt.check_model(e, f"{p + "/schedule"}/{i0}", x0)
        self._check_object(p, e, conditionals=[{'prop': 'mode', 'values': ['fixed'], 'presence': True, 'then': {'required': ['level']}, 'else': None}, {'prop': 'mode', 'values': ['lux'], 'presence': True, 'then': {'required': ['lux_entity', 'min', 'max']}, 'else': None}, {'prop': 'mode', 'values': ['device_lux'], 'presence': True, 'then': {'required': ['min', 'max']}, 'else': None}, {'prop': 'mode', 'values': ['schedule'], 'presence': True, 'then': {'required': ['schedule']}, 'else': None}])


