class ClientConfig(_rt.ContractModel):
    """Payload of WS 'client_config' (answer to get_client_config). Contains the per-device HA token in
    clear text - transport only over the pinned TLS port or LAN. Profile model: access
    (member/guest), profile and the effective profile rules (rules) replace templates, app
    overrides, locked keys, settings flags and the per-device rights; the app applies rules only and
    never resolves anything itself. Hard checks of the hub independent of the resolver: a device
    without remote_access gets ha_url null; ha_token, ha_instance_id and ha_enforcement only when
    the device holds a key (rule control_path checked or direct, or hub with effective
    remote_access: a read-only key; kids.away ha with parental controls), else null;
    ha_enforcement.control_path is checked for hub.
    Schema: schemas/client-config.json
    """

    ha_token: StrictStr | None = Field(description='Per-device HA long-lived access token; null = fail closed (no token, admin session; a device that holds a key but whose token is not usable right now gets token_error). Only when the device holds a key: rule control_path checked or direct, or hub (“Hub only”) with effective remote_access, then the key of its read-only HA user (ha_enforcement.control_path checked; with parental controls kids.away ha). On hub without remote access always null: the device reads and switches through the hub. Null while access.hours.open is false. Always null on the wire for a watch (watchos, wearos): its access reaches it only sealed to its key (watch_access).', repr=False)
    token_error: StrictStr | None = Field(None, description="Present exactly when the device holds a Home Assistant key, its access is open and ha_token is null; then ha_enforcement is null too. pending = the token has not arrived from the integration yet, or the hub holds it back until the integration has the device's rule snapshot; decryption_failed = the stored token cannot be decrypted (the hub asks the integration for a new one). While access is open a device holds a key exactly when ha_enforcement or token_error is set. With token_error the app deletes any Home Assistant token it stored, uses none, keeps its stored Home Assistant address, shows that the connection to Home Assistant is being set up and waits for client_config_updated; it is on the hub path only by its rules (a device on Hub only with remote access keeps working through the hub at home). Apps treat an unknown value like pending.")
    ha_url: StrictStr | None = Field(description='External HA URL, only when rules.remote_access.value is true (also on the hub path): the URL the admin set in the hub, else what HA reports (external_url, else the Nabu Casa address; POST /api/integration/ha-url). null = no remote access for this device or no external address known: the app removes a stored external URL and reaches HA only in the home network. Guests may have remote access when their profile allows it. Changing the rule, an adjustment, its expiry or the URLs sends client_config_updated.')
    ha_internal_url: StrictStr | None
    ha_instance_id: StrictStr | None = Field(None, description="Home Assistant's instance ID (helpers.instance_id, the uuid of its Bonjour TXT record _home-assistant._tcp), reported by the integration (POST /api/integration/ha-url). The app accepts it only from the pinned hub (or the pairing channel) and keeps it as the second proof of the home network: when the hub does not answer, an HA announced over Bonjour with this uuid confirms the home network, so the HA token may go over http:// / ws://. null/missing = not known yet (only the hub proves the home network). Same value for every device of the hub; sent to devices on the hub path (rule control_path hub, or parental controls) only together with their HA key (ha_token). Off the hub path it may come while token_error is set.")
    home_networks: list[StrictStr] | None = Field(None, description="The household's additional home networks (CIDR), same list for every device (also guests and child devices). The app treats hosts inside them like local hosts: a pairing QR code or link naming such a host is accepted, a self-signed certificate of such a host may be pinned on first use while the home network is verified, and the address counts as an internal route. Absent = none (a hub always sends it).")
    ha_enforcement: ClientConfigHaEnforcement | None = Field(None, description='Control path in Home Assistant. Present exactly with an HA token; null without one: no key (rule control_path hub without remote access: the hub controls), or a key that is not usable yet (token_error set). While access is open a device holds a key exactly when ha_enforcement or token_error is set. Integration not responding (docs/enforcement.md, “Integration down”): with checked the app keeps showing everything and explains switching is not possible right now; it never falls back to direct actions.')
    tls_fingerprint: StrictStr | None = Field(None, description='Absent in the admin/ingress variant.')
    tls_port: StrictInt | None = Field(None, description='8100 when a certificate exists. Must stay an integer: the apps decode it strictly (known deviation D3, docs/protocol.md).')
    config_sensor: StrictStr
    notification_sensor: StrictStr | None = None
    home_title: StrictStr | None
    home_bg_light: StrictStr | None
    home_bg_dark: StrictStr | None
    control_mode: ControlModeValue = Field(description="Hub default control mode, clamped by rules.control_mode_max (the hub clamps the per-area and per-entity modes it delivers as well). Apps assume 'advanced' when missing (known deviation D2, docs/protocol.md).")
    access: ClientAccess
    profile: ClientProfile | None = Field(description='Profile of the device; null only in the admin/ingress variant (message set, rules empty).')
    rules: ResolvedRules = Field(description='Effective profile rules; {} only in the admin/ingress variant.')
    kids: ClientKids | None = Field(None, description='Only with parental controls (profile.child_protection). away tells whether and how the device controls away from home.')
    family: ClientFamily | None = None
    babysitter: ClientBabysitter | None = Field(None, description='Only on babysitter devices with the rule babysitter_requests (else missing or null).')
    quick_access: ClientConfigQuickAccess = Field(description='Quick access of this device, derived from rules.quick_access (off → enabled false, no entities; status/control → max) and resolved per entity (admin level or domain default, domain max, device max, read scope). Guests, and devices on Hub only without remote access (boundary hub_only): enabled false. The app keeps the newest copy in the App Group snapshot for its widgets and controls; before every action the extension rereads the check sensor (sensor), so a revocation acts on the next tap without the app. Changes are announced with client_config_updated.')
    settings_pin_hash: StrictStr | None = Field(description='PBKDF2-HMAC-SHA256, 100000 iterations, dkLen 32, hex (fixtures/crypto/settings-pin-vectors). Sent only when rules.app_settings.value is pin (the effective remote PIN: device PIN, or the profile PIN when the device has none or the profile PIN is fixed); otherwise null.')
    settings_pin_salt: StrictStr | None = Field(description='16 random bytes, hex. Sent only when rules.app_settings.value is pin; otherwise null.')
    settings_pin_source: RemotePinSourceValue | None = Field(None, description='Origin of settings_pin_hash/salt: profile or device PIN; null when no PIN is sent.')
    config_hash: StrictStr | None = Field(None, description='Hash of the canonical JSON of profile.rev, access and rules; changes whenever an effective value changes (drift display).')
    message: StrictStr | None = Field(None, description='Only in the admin/ingress variant.')

    def _check(self, p: str, e: list[str]) -> None:
        _rt.check_str(e, p + "/ha_instance_id", self.ha_instance_id, pattern=_RE_29)
        _rt.check_items(e, p + "/home_networks", self.home_networks, max_items=10, unique=True)
        for i0, x0 in enumerate(self.home_networks or ()):
            _rt.check_str(e, f"{p + "/home_networks"}/{i0}", x0, pattern=_RE_30, min_length=9, max_length=43)
        _rt.check_model(e, p + "/ha_enforcement", self.ha_enforcement)
        _rt.check_str(e, p + "/tls_fingerprint", self.tls_fingerprint, pattern=_RE_15)
        _rt.check_str(e, p + "/config_sensor", self.config_sensor, const=_ns.CONFIG_SENSOR)
        _rt.check_str(e, p + "/notification_sensor", self.notification_sensor, pattern=_RE_31)
        _rt.check_str(e, p + "/home_bg_light", self.home_bg_light, pattern=_RE_5)
        _rt.check_str(e, p + "/home_bg_dark", self.home_bg_dark, pattern=_RE_5)
        _rt.check_enum(e, p + "/control_mode", self.control_mode, ControlMode)
        _rt.check_model(e, p + "/access", self.access)
        _rt.check_model(e, p + "/profile", self.profile)
        _rt.check_model(e, p + "/rules", self.rules)
        _rt.check_model(e, p + "/kids", self.kids)
        _rt.check_model(e, p + "/family", self.family)
