class ClientOnboardConfirm(_rt.ContractModel):
    """The confirming device sets up the waiting device as kind with profile_id (from
    onboard_info.grant). Same checks as onboard_lookup plus: setup_devices allows kind, the kind
    fits the platform, the profile is offered for it (never stronger than the confirming device),
    the area choice, own_area_id and start_area lie in grant.areas, a guest or house sitter has
    expires_at (at most guest_access.max_hours ahead) and remote only with remote_choice, managers
    only with managers_choice, access_windows only with access_hours_choice. The hub creates the
    device (access guest for guest and house sitter, else member; profile; owner_label; own HA
    user), stores the choices as device adjustments (areas, panel_start, remote_access,
    access_hours), adds the child to the chosen family managers, records set_up_by, seals the secret
    to the session's key and sends onboard_ok to the waiting device; the confirming device gets
    onboard_confirm_ok. Single use: the session ends with the first successful confirm, decline,
    expiry or mismatch; a validation error (kind_not_allowed, profile_not_allowed,
    areas_not_allowed, expiry_not_allowed, managers_not_allowed, access_hours_not_allowed) keeps it
    open and counts as a failed attempt.
    Schema: schemas/ws/client/onboard_confirm.json
    """

    __fixed__: ClassVar[dict[str, str]] = {'type': 'onboard_confirm'}
    type: Literal['onboard_confirm'] = 'onboard_confirm'
    session_id: StrictStr
    public_key: StrictStr
    hub_id: StrictStr
    kind: ProfileKindValue = Field(description='Kind the device is set up as; one of onboard_info.grant.kinds.')
    profile_id: StrictStr = Field(description='Profile from grant.kinds[kind].profiles.')
    client_name: StrictStr | None = Field(None, description="Name of the new device (default: the name it sent), e.g. “Child's iPhone”, “Wall panel Kitchen”.")
    owner_label: StrictStr | None = Field(None, description='Whose device it is (person, child, guest, house sitter: the name, e.g. “Child”); empty or missing = household (wall panel, TV).')
    all_areas: StrictBool | None = Field(None, description='Area choice: every active area, also future ones. Only with grant.all_areas. Wins over area_ids. Ignored when the profile fixes areas.')
    area_ids: list[StrictStr] | None = Field(None, description="Area choice: ids from grant.areas. Exactly the confirming device's list = its tags (it also sees areas added later under them); otherwise one area pin per area. Missing with all_areas missing = the confirming device's own areas. Ignored when the profile fixes areas.")
    own_area_id: StrictStr | None = Field(None, description="Own area of the new device (the room it is in, e.g. the TV's room), from grant.areas.")
    start_area: StrictStr | None = Field(None, description='Wall panel on a tablet: start area (device adjustment of panel_start, mode area), from grant.areas; only with start_area_choice.')
    managers: list[StrictStr] | None = Field(None, description='Kind child with parental controls, only with grant.managers_choice: family manager devices (grant.managers) that manage the new child in addition to those with all_children. Empty = only those with all_children.')
    expires_at: StrictStr | None = Field(None, description='Guest and house sitter: end of the access (required, in the future, at most guest_access.max_hours = 90 days ahead). Not allowed for other kinds.')
    remote: StrictBool | None = Field(None, description='Guest and house sitter, only with remote_choice: remote access of the guest (device adjustment of remote_access until the access ends). Missing = profile value.')
    access_windows: list[AccessWindow] | None = Field(None, description='Optional, only with grant access_hours_choice (else access_hours_not_allowed): access hours of the new device, stored as a device adjustment of access_hours. Missing = profile value.')

    def _check(self, p: str, e: list[str]) -> None:
        _rt.check_str(e, p + "/session_id", self.session_id, pattern=_RE_35)
        _rt.check_str(e, p + "/public_key", self.public_key, pattern=_RE_36)
        _rt.check_str(e, p + "/hub_id", self.hub_id, pattern=_RE_1)
        _rt.check_enum(e, p + "/kind", self.kind, ProfileKind)
        _rt.check_str(e, p + "/profile_id", self.profile_id, pattern=_RE_1)
        _rt.check_str(e, p + "/client_name", self.client_name, min_length=1, max_length=100)
