class ProfileRuleValues(_rt.ContractModel):
    """Value of every profile rule, one property per key of data/profile-rules.json. Used for profile
    bodies (admin API: partial in writes, complete in answers), suggestions and resolver vectors;
    the resolved, typed form for the apps is resolved-rules.json (generated from this file by
    tools/profile_rules.py). Unknown keys answer 422.
    Schema: schemas/common/profile-rule-values.json
    """

    __closed__: ClassVar[bool] = True
    remote_access: StrictBool | None = Field(None, description="Control Home Assistant from outside the home network (the device's HA user is not local_only).")
