    panel_night: ProfileRuleValuesPanelNight | None = None
    panel_remote: StrictBool | None = Field(None, description='Home Assistant may control this panel (brightness, wake, screensaver, start area, reload) through the entities of the integration. Only HA administrators and automations operate them, never device users. Off = the hub rejects every panel_command with remote_off and the integration creates no control entities. On in the suggestions wall panel, Apple TV and kids room wall panel, off in every other suggestion (the catalog default stays on, so profiles copied before this default existed keep their value).')
