class DataRoomClimate(_rt.ContractModel):
    """The one source for which entities give an area's room temperature and humidity (area cards, the
    climate capsule, wall panel, TV tiles, widgets, watch). Per measure: entities of device_domains
    (thermostats) read device_attribute and come before sensors of sensor_device_class. Entities
    whose text matches an exclude group (fridge, freezer, cool box, pool, outdoor, boiler, water,
    processor ...) or whose registry entity_category is listed never count automatically; the admin
    may still pick one on purpose. Text = entity_id, the placement's display name, friendly_name
    and, where known (hub), the registry names and the device's name and model. Matching: lower
    case, ä→ae, ö→oe, ü→ue, ß→ss, other diacritics dropped, every run of other characters than a-z
    and 0-9 becomes one space; a keyword of contains matches anywhere (German compounds), one of
    prefixes only at the start of a word. Keywords are stored in that normalized form, with the
    spelling Home Assistant uses in entity ids (kuhlschrank) next to the transcribed one
    (kuehlschrank). docs/room-climate.md, reference tools/room_climate_ref.py. Generated as a
    constant for every language (codegen ContractData).
    Schema: schemas/data/room-climate.json
    """

    __closed__: ClassVar[bool] = True
    version: StrictInt = Field(description='Raised on every change of this file.')
    measures: DataRoomClimateMeasures
    exclude: DataRoomClimateExclude

    def _check(self, p: str, e: list[str]) -> None:
        _rt.check_num(e, p + "/version", self.version, minimum=1)
