    entity_id: StrictStr | None = None
    action: StrictStr | None = None
    route: ControlRouteValue | None = None
    origin: ControlOriginValue | None = None
    reason: ControlDenialReasonValue | None = Field(None, description='denied: why; control: null.')
    count: StrictInt | None = Field(None, description='Occurrences merged into this event (direct_access_attempt: rejected direct actions in the window). Missing = 1.')
    since: StrictStr | None = Field(None, description='integration_outage: last sign of life before the gap; direct_access_attempt: first attempt in the window.')
    ha_group: HaUserGroupValue | None = Field(None, description='rules_applied, access_group_restored: group the device user has now.')
    rules_hash: StrictStr | None = Field(None, description='rules_applied: the snapshot now in force.')
    reliability: EnforcementEventReliabilityValue | None = Field(None, description='best_effort = detected on a best-effort basis (direct_access_attempt, integration_outage); may miss occurrences. Missing = exact.')
    version: StrictStr | None = Field(None, description='integration_started: version of the integration.')

    def _check(self, p: str, e: list[str]) -> None:
        _rt.check_str(e, p + "/id", self.id, pattern=_RE_1)
        _rt.check_enum(e, p + "/type", self.type, EnforcementEventType)
        _rt.check_str(e, p + "/client_id", self.client_id, pattern=_RE_1)
        _rt.check_str(e, p + "/ha_user_id", self.ha_user_id, pattern=_RE_29)
        _rt.check_str(e, p + "/entity_id", self.entity_id, pattern=_RE_3, max_length=255)
        _rt.check_str(e, p + "/action", self.action, pattern=_RE_19)
        _rt.check_enum(e, p + "/route", self.route, ControlRoute)
        _rt.check_enum(e, p + "/origin", self.origin, ControlOrigin)
        _rt.check_enum(e, p + "/reason", self.reason, ControlDenialReason)
        _rt.check_num(e, p + "/count", self.count, minimum=1, maximum=100000)
        _rt.check_enum(e, p + "/ha_group", self.ha_group, HaUserGroup)
        _rt.check_str(e, p + "/rules_hash", self.rules_hash, pattern=_RE_15)
        _rt.check_enum(e, p + "/reliability", self.reliability, EnforcementEventReliability)
        _rt.check_str(e, p + "/version", self.version, max_length=32)
        self._check_object(p, e, conditionals=[{'prop': 'type', 'values': ['control', 'denied'], 'presence': False, 'then': {'required': ['client_id', 'entity_id', 'action', 'route']}, 'else': None}, {'prop': 'type', 'values': ['denied'], 'presence': False, 'then': {'required': ['reason']}, 'else': None}, {'prop': 'type', 'values': ['access_group_restored', 'direct_access_attempt', 'rules_applied'], 'presence': False, 'then': {'required': ['client_id']}, 'else': None}, {'prop': 'type', 'values': ['integration_outage'], 'presence': False, 'then': {'required': ['since']}, 'else': None}])


