class EnforcementSnapshot(_rt.ContractModel):
    """What the hub hands the integration per paired device so Home Assistant can enforce operating
    without asking the hub: the device's HA user, the control path and per entity what the device
    may do on the local and the external route and from quick access, plus the kids rules with
    parental controls. The hub resolves everything (profile, adjustments, boundaries, areas, own
    area, remote_control, quick access, kids layers); the integration only looks entries up.
    Entities that are not listed are not controllable (blocked_area). Hiding stays a display rule:
    Home Assistant always lets a device user read every entity. The integration stores the last
    snapshot per device in .storage and keeps deciding with it while the hub is unreachable; it
    applies a snapshot only to the HA user it created for client_id (never to other users) and only
    when rules_hash matches. kids is an object exactly with parental controls (checked by
    tools/validate.py). access: access switch and access hours, evaluated by the integration with
    its own clock. home_networks: extra networks that count as the local route. location: effective
    rule location for <ns>.report_location.
    Schema: schemas/common/enforcement-snapshot.json
    """

    __closed__: ClassVar[bool] = True
    version: StrictInt = Field(description='Snapshot format; an integration ignores a version it does not know (the device then has no snapshot: rules_missing).')
    client_id: StrictStr
    ha_user_id: StrictStr = Field(description="HA user of the device as delivered with POST /api/integration/client-token; must equal the integration's own mapping.")
    issued_at: StrictStr
    rules_hash: StrictStr
    control_path: ControlPathValue = Field(description='Control path of the device in Home Assistant: checked for the rule values hub and checked (the integration keeps the device user in system-read-only), direct for direct (profiles_ref.snapshot_control_path).')
    remote_access: StrictBool = Field(description='Effective rule remote_access. false = nothing from the external route (blocked_remote), in addition to local_only of the HA user.')
    child_protection: StrictBool = Field(description='Parental controls: the hub controls for the device where it is reachable (grant), the device itself only when it holds a key; kids is then an object and every kids rule applies to every call.')
    entities: dict[str, Any] = Field(description='entity_id -> access. Everything the device may operate somewhere (areas incl. own area, run targets of its tiles, kids exceptions). Group entities are checked member by member: each member must be listed as well.')
    kids: EnforcementKids | None
    access: EnforcementAccess | None = Field(description='Access switch and access hours; null = neither (no restriction). While closed every entity is refused with blocked_access_closed.')
    home_networks: list[StrictStr] = Field(description="The household's additional home networks, the same in every snapshot (part of rules_hash, so a change makes the integration fetch all snapshots again). A caller whose address lies inside one of them is on the local route of <ns>.control, like the built-in local ranges.")
    location: EnforcementSnapshotLocationValue = Field(description='Effective rule location (off when it does not apply: kind, platform, guest boundary, expired guest). <ns>.report_location and client_location are checked against it; off makes the integration clear the device_tracker.')

    def _check(self, p: str, e: list[str]) -> None:
        _rt.check_num(e, p + "/version", self.version, const=1)
        _rt.check_str(e, p + "/client_id", self.client_id, pattern=_RE_1)
        _rt.check_str(e, p + "/ha_user_id", self.ha_user_id, pattern=_RE_29)
        _rt.check_str(e, p + "/rules_hash", self.rules_hash, pattern=_RE_15)
        _rt.check_enum(e, p + "/control_path", self.control_path, ControlPath)
        _rt.check_map(e, p + "/entities", self.entities, max_properties=10000)
        _rt.check_model(e, p + "/kids", self.kids)
        _rt.check_model(e, p + "/access", self.access)
        _rt.check_items(e, p + "/home_networks", self.home_networks, max_items=10, unique=True)
        for i0, x0 in enumerate(self.home_networks or ()):
            _rt.check_str(e, f"{p + "/home_networks"}/{i0}", x0, pattern=_RE_30, min_length=9, max_length=43)
        _rt.check_enum(e, p + "/location", self.location, EnforcementSnapshotLocation)
        self._check_object(p, e, conditionals=[{'prop': 'child_protection', 'values': [True], 'presence': False, 'then': {'consts': {'control_path': 'checked'}, 'non_null': ['kids']}, 'else': None}])


