class IntegrationClientTokenRequest(_rt.ContractModel):
    """The integration delivers the long-lived access token of a device's own HA user. Integration
    token only. Idempotent: the same refresh_token_id again is acknowledged with unchanged=true and
    nothing is re-sent to the app; a different refresh_token_id replaces the stored token (rotation)
    and the hub pushes client_config_updated to the device, waits for its get_client_config (max 5
    s) plus 3 s, then answers. The integration removes every other token of that HA user only AFTER
    the 200. The bearer is stored encrypted, never logged, never returned. Binding: the hub accepts
    a delivery only (a) while the device waits for its token (ha_token_status pending, listed in
    provisioning[]), (b) with the request_id of an open rotation of this device, or (c) unsolicited
    for the HA user already stored for the device (the integration rotates on its own when
    local_only changes or a guest token no longer covers the expiry). Anything else is answered 422
    request_required. Under the Supervisor the integration token itself is accepted only from the
    hub's own host (Home Assistant Core), never from the LAN or other add-ons.
    Schema: schemas/integration/client-token.request.json
    """

    __closed__: ClassVar[bool] = True
    client_id: StrictStr
    ha_user_id: StrictStr
    refresh_token_id: StrictStr
    token: StrictStr = Field(description="HA access token (JWT) of the device's long-lived refresh token.", repr=False)
    request_id: StrictStr | None = Field(None, description='Echo of provision_client.request_id / provisioning[].request_id, if the delivery answers a request. Required to deliver a token for a different HA user than the stored one outside the pending phase.')

    def _check(self, p: str, e: list[str]) -> None:
        _rt.check_str(e, p + "/client_id", self.client_id, pattern=_RE_1)
        _rt.check_str(e, p + "/ha_user_id", self.ha_user_id, min_length=1, max_length=128)
        _rt.check_str(e, p + "/refresh_token_id", self.refresh_token_id, min_length=1, max_length=128)
        _rt.check_str(e, p + "/token", self.token, min_length=1, max_length=4096)
        _rt.check_str(e, p + "/request_id", self.request_id, pattern=_RE_1)
        self._check_object(p, e)


