class ProvisionRequest(_rt.ContractModel):
    """Asks the integration to make sure the device has its own HA user with exactly one long-lived
    access token and to deliver that token via POST /api/integration/client-token. Sent as WS push
    provision_client and repeated in GET /api/integration/status provisioning[] until the hub has
    the token. Handling MUST be idempotent: token_action=ensure reuses the device's existing token
    (a new access token is derived from the same refresh token, refresh_token_id stays the same);
    only token_action=rotate mints a new one.
    Schema: schemas/common/provision-request.json
    """

    client_id: StrictStr
    display_name: StrictStr
    owner_label: StrictStr | None = None
    is_guest: StrictBool
    remote_allowed: StrictBool = Field(description='Device may use HA from outside the local network: the effective profile rule remote_access. Default false (local-first); also for guests when their profile allows it and for devices with parental controls (read-only key, docs/enforcement.md §7).')
    guest_expires_at: StrictStr | None = Field(None, description='Guest expiry (UTC). The integration bounds the HA-side token lifetime to expiry + 7 days grace and rotates the token when an extension is no longer covered.')
    request_id: StrictStr | None = Field(None, description='Correlation id for logs; not used for deduplication.')
    token_action: ProvisionRequestTokenActionValue = Field(description='ensure: create user/token if missing, otherwise re-deliver the current token. rotate: mint a new token for the same user; the integration removes the old one only after the hub acknowledged the new one.')
    reason: ProvisionRequestReasonValue = Field(description='Why the hub asks (logging, UI). pair = newly paired device (status pending); retry = earlier request unanswered; rotate = admin rotate-token; guest_extend = guest extended beyond the token lifetime; reprovision = the hub has no usable token for an active device (e.g. restored backup).')

    def _check(self, p: str, e: list[str]) -> None:
        _rt.check_str(e, p + "/client_id", self.client_id, pattern=_RE_1)
        _rt.check_str(e, p + "/display_name", self.display_name, min_length=1, max_length=100)
        _rt.check_str(e, p + "/owner_label", self.owner_label, max_length=50)
        _rt.check_str(e, p + "/guest_expires_at", self.guest_expires_at, fmt='date-time')
        _rt.check_str(e, p + "/request_id", self.request_id, pattern=_RE_1)
        _rt.check_enum(e, p + "/token_action", self.token_action, ProvisionRequestTokenAction)
        _rt.check_enum(e, p + "/reason", self.reason, ProvisionRequestReason)
        self._check_object(p, e, conditionals=[{'prop': 'is_guest', 'values': [True], 'presence': True, 'then': {'required': ['guest_expires_at'], 'non_null': ['guest_expires_at']}, 'else': None}])


