class ProfilesResolve(_rt.ContractModel):
    """Test vector of the profile resolver, shared by hub (resolver tests) and apps (display of
    source/reason/locked, user's choice, temporary adjustments). input.profile: from_suggestion =
    copy of that suggestion (data/profile-suggestions.json), else an empty profile (catalog
    defaults, nothing fixed, no user's choice); child_protection, fixed and user_choice replace,
    rules are merged per key. expected lists the asserted rules (missing user_choice/expires_at/then
    = false/null). tools/validate.py recomputes every vector with tools/profiles_ref.py. Apps: drop
    rules with source not_applicable to get client_config.rules. entity_checks: per entity and route
    what the app and quick access may do (tools/profiles_ref.py entity_access). notification_checks
    and expected_remote_pin_source as well; expected_ha_user_group.
    Schema: schemas/profiles/resolve.json
    """

    __closed__: ClassVar[bool] = True
    description: StrictStr
    input: ProfilesResolveInput
    expected: dict[str, Any]
    entity_checks: list[ProfilesResolveEntityChecksItem] | None = None
    expected_remote_pin_source: RemotePinSourceValue | None = Field(None, description='Expected origin of the effective remote PIN (tools/profiles_ref.py remote_pin_source).')
    notification_checks: list[ProfilesResolveNotificationChecksItem] | None = Field(None, description='Rule notification_level: whether the app shows a notification (tools/profiles_ref.py notification_shown); no delivery promise.')
    expected_ha_user_group: HaUserGroupValue | None = Field(None, description="Group of the device's Home Assistant user from the effective control_path (tools/profiles_ref.py ha_user_group).")
    expected_ha_access: ProfilesResolveExpectedHaAccess | None = Field(None, description="Home Assistant access fields for this device (tools/profiles_ref.py ha_access) with the given access state; for a watch (input.limit) with its phone's effective rules at the same moment.")

    def _check(self, p: str, e: list[str]) -> None:
        _rt.check_str(e, p + "/description", self.description, min_length=1)
        _rt.check_model(e, p + "/input", self.input)
        for i0, x0 in enumerate(self.entity_checks or ()):
            _rt.check_model(e, f"{p + "/entity_checks"}/{i0}", x0)
        _rt.check_enum(e, p + "/expected_remote_pin_source", self.expected_remote_pin_source, RemotePinSource)
