    control_path: ControlPathRuleValue | None = Field(None, description="Effective Home Assistant access of the device (rule control_path after the platform mapping: on tvos, android_tv, watchos and wearos hub is checked). hub = no key unless remote access gives a read-only one (has_ha_token), checked = read-only key, direct = full key. null = the hub could not resolve the device's rules (the cause is in the hub's log; remote_allowed is null too): the key state is unknown, and has_ha_token then only says whether a token exists at all. Missing on older hubs.")
    owner_label: StrictStr | None
    profile_id: StrictStr
    profile_name: StrictStr
    child_protection: StrictBool = Field(description='Parental controls of the profile (kids rules enforced by the hub and the integration; whether the device holds a Home Assistant key is set by the rule control_path, has_ha_token).')
