    temporary_override_count: StrictInt
    has_remote_pin: StrictBool
    remote_allowed: StrictBool | None = Field(description="Effective rule remote_access (read only; changed through the profile or an adjustment). The HA user of the device is local_only exactly when this is false. null = the device's rules could not be resolved: only together with control_path null; then access, remote access and key level are unknown.")
    ha_user_id: StrictStr | None = Field(description='HA user of this device (set by the integration); null while pending.')
    ha_token_status: HaTokenStatusValue = Field(description='HA user of the device on the hub: pending = waiting for the integration to create the user and deliver its token; active = user and token stored on the hub. On the hub path active means the hub holds the token for its calls of <ns>.control; the device itself holds it only when it holds a key (has_ha_token).')
    ha_token_pending_since: StrictStr | None = Field(None, description='UTC timestamp since the device waits for its token, null when not pending.')
    platform: PlatformValue | None = Field(description='Last reported by the app in auth/pair; null until reported.')
