class RestProfile(_rt.ContractModel):
    """A profile: GET /api/profiles/{profile_id}, answer of every profile write. One profile per
    device; profiles are created freely by the admin (max limits.max_profiles), from a suggestion,
    from a device or empty.
    Schema: schemas/rest/profile.json
    """

    id: StrictStr
    name: StrictStr
    kind: ProfileKindValue = Field(description='Kind of the profile: groups profiles for “Set up new devices” (rule setup_devices) and the gallery; independent of child_protection. Only kind person may have setup_devices (other kinds resolve it to not_applicable, reason requires_profile_kind).')
    description: StrictStr | None = Field(description='One sentence for the profile card.')
    icon: StrictStr | None
    color: StrictStr | None
    child_protection: StrictBool = Field(description='Parental controls. Not for a profile with guest devices (422 profile.guest_child_protection).')
    rules: ProfileRuleValues = Field(description='Answers: every rule of the catalog (defaults filled in, see catalog_defaults).')
    fixed: list[ProfileRuleKeyValue] = Field(description='Rules with checkbox “Fixed”: no device adjustment possible. Always contains the rules without checkbox.')
    user_choice: list[ProfileRuleKeyValue] = Field(description='Rules where the person at the device decides (value = starting value).')
    origin: RestProfileOrigin | None = Field(description='Suggestion the profile was copied from (information only; a later suggestion version never changes the profile).')
    suggestion_update: RestProfileSuggestionUpdate | None = Field(description='A newer version of the origin suggestion exists (POST /api/profiles/{profile_id}/apply-suggestion, only on request).')
    catalog_defaults: list[ProfileRuleKeyValue] = Field(description='Rules the profile does not contain yet (added by a hub update); they use the catalog default until the profile is saved.')
    default_for: list[DefaultProfileSlotValue] = Field(description='Device types this profile is the default profile of.')
    device_count: StrictInt
    adjusted_device_count: StrictInt = Field(description='Devices with at least one adjustment.')
    guest_device_count: StrictInt
    rev: StrictInt
    created_at: StrictStr
    updated_at: StrictStr
    updated_by: StrictStr | None
    has_remote_pin: StrictBool = Field(description='The profile has its own remote PIN for “settings with remote PIN”: valid for every device of the profile; a device PIN wins unless remote_pin_fixed. Never returned, only this flag.')
    remote_pin_fixed: StrictBool = Field(description='Checkbox “Fixed” of the profile PIN: device PINs are ignored and PUT …/remote-pin answers 422 remote_pin.fixed.')
    scene_hints: list[SceneHint] | None = Field(None, description='Released scenes and scripts with targets this profile may not switch (docs/enforcement.md §2 step 4), computed for the profile without a device (no own area, no adjustments). Only in GET and PATCH /api/profiles/{profile_id}; empty when Home Assistant is not reachable. At most 50.')
    hub_remote_pairing: RestProfileHubRemotePairing | None = Field(None, description='Per access (member, guest) and platform: whether a device paired with this profile now would be Hub only with remote access (it would hold the read-only key because of remote access; a new device has no adjustment). Always false on tvos, android_tv, watchos and wearos. Missing on older hubs.')

    def _check(self, p: str, e: list[str]) -> None:
        _rt.check_str(e, p + "/id", self.id, pattern=_RE_1)
        _rt.check_str(e, p + "/name", self.name, pattern=_RE_26, min_length=1, max_length=40)
        _rt.check_enum(e, p + "/kind", self.kind, ProfileKind)
        _rt.check_str(e, p + "/description", self.description, max_length=300)
        _rt.check_str(e, p + "/icon", self.icon, pattern=_RE_43)
        _rt.check_str(e, p + "/color", self.color, pattern=_RE_74)
        _rt.check_model(e, p + "/rules", self.rules)
        _rt.check_items(e, p + "/fixed", self.fixed, unique=True)
        for i0, x0 in enumerate(self.fixed or ()):
            _rt.check_enum(e, f"{p + "/fixed"}/{i0}", x0, ProfileRuleKey)
        _rt.check_items(e, p + "/user_choice", self.user_choice, unique=True)
        for i0, x0 in enumerate(self.user_choice or ()):
            _rt.check_enum(e, f"{p + "/user_choice"}/{i0}", x0, ProfileRuleKey)
        _rt.check_model(e, p + "/origin", self.origin)
        _rt.check_model(e, p + "/suggestion_update", self.suggestion_update)
        _rt.check_items(e, p + "/catalog_defaults", self.catalog_defaults, unique=True)
        for i0, x0 in enumerate(self.catalog_defaults or ()):
            _rt.check_enum(e, f"{p + "/catalog_defaults"}/{i0}", x0, ProfileRuleKey)
        _rt.check_items(e, p + "/default_for", self.default_for, unique=True)
        for i0, x0 in enumerate(self.default_for or ()):
            _rt.check_enum(e, f"{p + "/default_for"}/{i0}", x0, DefaultProfileSlot)
        _rt.check_num(e, p + "/device_count", self.device_count, minimum=0)
        _rt.check_num(e, p + "/adjusted_device_count", self.adjusted_device_count, minimum=0)
        _rt.check_num(e, p + "/guest_device_count", self.guest_device_count, minimum=0)
        _rt.check_num(e, p + "/rev", self.rev, minimum=1)
        _rt.check_str(e, p + "/updated_by", self.updated_by, max_length=100)
        _rt.check_items(e, p + "/scene_hints", self.scene_hints, max_items=50)
        for i0, x0 in enumerate(self.scene_hints or ()):
            _rt.check_model(e, f"{p + "/scene_hints"}/{i0}", x0)
        _rt.check_model(e, p + "/hub_remote_pairing", self.hub_remote_pairing)


