class RestRotateTokenResponse(_rt.ContractModel):
    """Admin only. The rotation is stored first and survives a hub restart. 200: the integration
    delivered the new token within the wait time (ha_token_status, ha_token_minted_at; the app was
    told via client_config_updated). 202 status rotation_requested: sent to the integration, no
    answer yet. 202 status pending: the integration is not connected; the rotation runs as soon as
    it is (provisioning[] on its next poll, retry loop once its push session is up), answered at
    once. 202 status pending also for a device with remote access (remote_allowed) that is not
    connected to the hub (away): the rotation is deferred until the device connects to the hub (it
    is home and fetches the new token at once), at the latest after 72 h; then it runs anyway (audit
    log, no endless deferral). There is no separate status value for this; the admin UI tells the
    case apart by remote_allowed and is_connected of the device. 404 unknown device, 409 device not
    active or without an HA token. There is no 503.
    Schema: schemas/rest/rotate-token.response.json
    """

    __closed__: ClassVar[bool] = True
    ok: StrictBool
    client_id: StrictStr
    ha_token_status: HaTokenStatusValue | None = None
    ha_token_minted_at: StrictStr | None = None
    status: RestRotateTokenResponseStatusValue | None = Field(None, description='202: rotation_requested (sent, waiting for the integration) or pending (integration not connected, or a device with remote access that is away: deferred until it connects, max. 72 h). 200: null.')

    def _check(self, p: str, e: list[str]) -> None:
        _rt.check_bool(e, p + "/ok", self.ok, const=True)
        _rt.check_str(e, p + "/client_id", self.client_id, pattern=_RE_1)
        _rt.check_enum(e, p + "/ha_token_status", self.ha_token_status, HaTokenStatus)
        _rt.check_enum(e, p + "/status", self.status, RestRotateTokenResponseStatus)
        self._check_object(p, e)


