class SetupGrant(_rt.ContractModel):
    """What a device with the rule setup_devices may give when it sets up a new device
    (onboard_info.grant) or invites a guest (setup_grant): the allowed kinds with their profiles,
    its own areas, the family managers and the guest limits. The hub offers only profiles whose
    rights are not stronger than the confirming device's own (docs/setup.md “No escalation”): every
    rule of security critical or sensitive outside the kids and location groups, compared along
    order, setup_devices by kinds, remote_control per level and the areas a fixed profile shows.
    Profiles that do not pass are left out; kinds without any profile are left out.
    Schema: schemas/common/setup-grant.json
    """

    tags: list[StrictStr] = Field(description='Tags of the confirming device; a new device gets them when the area choice is the whole list.')
    all_areas: StrictBool = Field(description='true = the confirming device sees every active area; only then may it choose “All areas”.')
    areas: list[SetupGrantAreasItem] = Field(description='Active areas the confirming device sees itself, in display order: the choice for the new device (areas, own area, start area).')
    kinds: list[SetupGrantKindsItem] = Field(description='Allowed kinds in the order of data/profile-rules.json profile_kinds: in setup_devices.kinds of the confirming device, fitting the platform of the waiting device (profile_kinds[].platforms; for an invitation: guest only) and with at least one profile. A watch session (own_watch) has exactly its default profile.')
    managers_choice: StrictBool = Field(description='true = the confirming device has the right family_manager: it chooses the managers of a new child (onboard_confirm.managers, preselect itself). false = a new child is managed by every family manager with “all children” automatically.')
    managers: list[SetupGrantManagersItem] = Field(description='Family manager devices (effective rule family_manager): all_children = manages every child, also a new one (cannot be deselected); otherwise only the chosen children.')
    guest_access: SetupGrantGuestAccess = Field(description='Limits of a guest or house sitter (data/profile-rules.json guest_access): expires_at at most max_hours (90 days) ahead.')
    own_watch: StrictBool = Field(description="true = the waiting device is a watch: the phone sets up its own watch (needs its rule watch) with the watch's default profile, no other choice. Also true for the child's phone of a child_watch session (role child).")
    child_watch: SetupGrantChildWatch | None = Field(None, description="Present only for the watch of a device with parental controls (docs/setup.md “A child's watch”). Absent = no child's watch.")

    def _check(self, p: str, e: list[str]) -> None:
        _rt.check_items(e, p + "/areas", self.areas, max_items=200)
        for i0, x0 in enumerate(self.areas or ()):
            _rt.check_model(e, f"{p + "/areas"}/{i0}", x0)
        _rt.check_items(e, p + "/kinds", self.kinds, max_items=7)
        for i0, x0 in enumerate(self.kinds or ()):
            _rt.check_model(e, f"{p + "/kinds"}/{i0}", x0)
        _rt.check_items(e, p + "/managers", self.managers, max_items=100)
        for i0, x0 in enumerate(self.managers or ()):
            _rt.check_model(e, f"{p + "/managers"}/{i0}", x0)
        _rt.check_model(e, p + "/guest_access", self.guest_access)
        _rt.check_model(e, p + "/child_watch", self.child_watch)


