class ServerOnboardOk(_rt.ContractModel):
    """The onboarding was confirmed; the connection is authenticated as the new device (like pair_ok).
    For a watch (platform watchos or wearos, opened by its phone with the watch's key) the hub does
    not authenticate the connection: it sends onboard_ok and closes with 1000, so the phone never
    reads the watch's client_config; the watch's HA access follows sealed to the same key in
    watch_access. The client secret is never sent in clear: sealed is an HPKE base-mode message (RFC
    9180, DHKEM(X25519, HKDF-SHA256), HKDF-SHA256, ChaCha20Poly1305; info = "hub/onboard/v1", aad =
    session_id as ASCII) to the session's public key. Plaintext: JSON {"client_id", "secret"}; the
    device checks that client_id equals the outer client_id. Known-answer vectors:
    fixtures/crypto/onboard-seal-vectors. Carries the protocol fields like pair_ok.
    Schema: schemas/ws/server/onboard_ok.json
    """

    __fixed__: ClassVar[dict[str, str]] = {'type': 'onboard_ok'}
    type: Literal['onboard_ok'] = 'onboard_ok'
    client_id: StrictStr
    client_name: StrictStr
    sealed: ServerOnboardOkSealed = Field(repr=False)
    protocol_version: StrictInt
    min_protocol_version: StrictInt
    min_app_version: MinAppVersion

    def _check(self, p: str, e: list[str]) -> None:
        _rt.check_str(e, p + "/client_id", self.client_id, pattern=_RE_1)
        _rt.check_model(e, p + "/sealed", self.sealed)
        _rt.check_num(e, p + "/protocol_version", self.protocol_version, minimum=1)
        _rt.check_num(e, p + "/min_protocol_version", self.min_protocol_version, minimum=1)
        _rt.check_model(e, p + "/min_app_version", self.min_app_version)


